        private static $tables = ['automatewoo_abandoned_carts', 'automatewoo_events', 'automatewoo_customer_meta', 'automatewoo_customers', 'automatewoo_guest_meta', 'automatewoo_guests', 'automatewoo_log_meta', 'automatewoo_logs', 'automatewoo_queue_meta', 'automatewoo_queue'];
